mapper.select:
SELECT pay05_relate_appr_id                                                                      AS relate_appr_id,
       pay05_appr_id                                                                             AS appr_id,
       b.apr01_status_cd                                                                         AS status_code,
       f_cdnm('AprStatusCode', b.apr01_status_cd, pay05_company_id, b.apr01_reg_date)            AS status_name
  FROM pay05_relate_appr
       LEFT OUTER JOIN apr01_appr b ON pay05_appr_id = apr01_appr_id
 WHERE pay05_company_id = #{companyId}
   AND pay05_pay_cd     = #{payCode}
   AND pay05_start_date = #{payDate}

mapper.insert:
INSERT INTO pay05_relate_appr (pay05_relate_appr_id, pay05_company_id, pay05_start_date, pay05_pay_cd, pay05_retire_id)
SELECT #{relateApprId}, pay10_company_id, pay10_date, pay10_pay_cd, pay10_month_id
  FROM pay10_month
 WHERE pay10_month_id   = #{monthId}
   AND pay10_company_id = #{companyId}
   AND pay10_pay_cd     = '03'

mapper.update:
UPDATE pay05_relate_appr
   SET pay05_appr_id    = #{apprId}
     , pay05_account_id = (SELECT pay03_account_id
                             FROM pay03_account
                            WHERE pay03_company_id = pay05_company_id
                              AND pay03_start_date <= pay05_start_date
                            ORDER BY pay03_start_date DESC
                            LIMIT 1)
 WHERE pay05_relate_appr_id = #{relateApprId}
   AND pay05_company_id     = #{companyId}
